		if(s[i] == 'R') y++;
		if(s[i] == 'U') x--;
		if(s[i] == 'D') x++;
		vis[x][y] = 0;

	}
	int ans = bfs(xx, yy, x, y);

	if(ans == len) printf("OK\n");
	else printf("BUG\n");
	return 0;
}
